    ): ApiResult = withContext(Dispatchers.IO) {
        val url = buildString {
            append(serverUrl).append(path)
            if (query.isNotEmpty()) {
                append('?')
                append(query.entries.joinToString("&") { (k, v) ->
                    k + "=" + java.net.URLEncoder.encode(v, "UTF-8")
                })
