        return if (res.ok) res.jsonArray() else JSONArray()
    }

    // ── Student mark ────────────────────────────────────────────────────
    suspend fun submitAttendance(
        token: String,
        latitude: Double,
        longitude: Double,
        accuracy: Float,
        selfieBase64: String,
    ): JSONObject = requireOk(
        request(
            "/api/functions/submit-attendance",
            "POST",
            JSONObject()
                .put("token", token)
                .put("location", JSONObject().put("latitude", latitude).put("longitude", longitude).put("accuracy", accuracy))
                .put("selfieDataUrl", selfieBase64)
                .put("selfieCapturedAt", System.currentTimeMillis())
                .put("device", JSONObject().put("platform", "android-native").put("uuid", deviceUuid()))
        ),
        "Mark attendance"
    )

    private fun deviceUuid(): String {
        val sp = context.getSharedPreferences("attendx_server", Context.MODE_PRIVATE)
        var id = sp.getString("device_uuid", null)
        if (id == null) {
            id = java.util.UUID.randomUUID().toString()
            sp.edit().putString("device_uuid", id).apply()
        }
        return id
    }

    companion object {
        const val DEFAULT_SERVER = "https://attendx-lilac-zeta.vercel.app"
    }
}

package com.attendx.app.api

import android.content.Context
import org.json.JSONObject

data class Session(
    val token: String,
    val userId: String,
    val email: String,
    val role: String,
    val fullName: String,
    val identifier: String,
    val department: String,
    val approvalStatus: String,
)

class SessionStore(context: Context) {
    private val prefs = context.getSharedPreferences("attendx_session", Context.MODE_PRIVATE)

    fun save(token: String, profile: JSONObject, user: JSONObject?) {
        val userId = profile.optString("id").ifEmpty { user?.optString("id").orEmpty() }
        val role = profile.optString("role").ifEmpty { user?.optString("role").orEmpty() }
        prefs.edit()
            .putString("token", token)
            .putString("user_id", userId)
            .putString("email", profile.optString("email"))
            .putString("role", role)
            .putString("full_name", profile.optString("full_name"))
            .putString("identifier", profile.optString("identifier"))
            .putString("department", profile.optString("department"))
            .putString("approval_status", profile.optString("approval_status"))
            .apply()
    }

    fun load(): Session? {
        val token = prefs.getString("token", null) ?: return null
        return Session(
            token = token,
            userId = prefs.getString("user_id", "") ?: "",
            email = prefs.getString("email", "") ?: "",
            role = prefs.getString("role", "") ?: "",
            fullName = prefs.getString("full_name", "") ?: "",
            identifier = prefs.getString("identifier", "") ?: "",
            department = prefs.getString("department", "") ?: "",
            approvalStatus = prefs.getString("approval_status", "") ?: "",
        )
    }

    fun clear() {
        prefs.edit().clear().apply()
    }
}

fun AppRoot() {
    val context = LocalContext.current
    val api = remember { Api(context) }
    val sessionStore = remember { SessionStore(context) }

    var screen by remember { mutableStateOf<Screen>(Screen.Splash) }
    var devBlocked by remember { mutableStateOf(false) }
    var session by remember { mutableStateOf<Session?>(null) }

    LaunchedEffect(Unit) {
        devBlocked = isDeveloperModeEnabled(context)
        session = sessionStore.load()
        screen = if (devBlocked) Screen.DevModeBlocked else when {
            session == null -> Screen.Login
            session!!.approvalStatus == "pending" -> Screen.PendingApproval
            session!!.approvalStatus == "approved_waiting_code" -> Screen.PendingApproval
            else -> Screen.Workspace
        }
    }

    AttendXTheme {
        Scaffold(modifier = Modifier.fillMaxSize()) { inner ->
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .safeDrawingPadding()
                    .padding(inner),
            ) {
                when (val s = screen) {
                    Screen.Splash -> SplashScreen()
                    Screen.DevModeBlocked -> DevModeBlockedScreen(onRecheck = {
                        devBlocked = isDeveloperModeEnabled(context)
                        if (!devBlocked) screen = if (session == null) Screen.Login else Screen.Workspace
                    })
                    Screen.Login -> LoginScreen(
                        api = api,
                        onSignedIn = { token, profile ->
                            sessionStore.save(token, profile, null)
                            session = sessionStore.load()
                            screen = when (session?.approvalStatus) {
                                "pending" -> Screen.PendingApproval
                                "approved_waiting_code" -> Screen.PendingApproval
                                else -> Screen.Workspace

)
                    Screen.PendingApproval -> PendingApprovalScreen(onSignOut = {
                        sessionStore.clear(); session = null; screen = Screen.Login
                    })
                    Screen.MustChangePassword -> ChangePasswordScreen(
                        api = api,
                        onDone = { screen = Screen.Workspace },
                        onSignOut = { sessionStore.clear(); session = null; screen = Screen.Login },
                    )
                    Screen.Workspace -> {
                        val active = session ?: return@Column
                        Workspace(
                            api = api,
                            session = active,
                            onSignOut = {
                                sessionStore.clear(); session = null; screen = Screen.Login
                            },
                            onMustChangePassword = { screen = Screen.MustChangePassword },
                        )
                    }
                }
            }
        }
    }
}

