try {
    if (cache && Date.now() - cache.at < CACHE_TTL_MS) {
      res.json({ ...cache.data, cached: true });
      return;
    }
    const data = fromEnv() || (await fetchFromGitHub());
    if (!data) {
      // No release metadata available — still hand back the releases page so
