export function generateTrackingId(): string {
  // Format: ATX-Q-XXXXXX (6 base36 chars) — collision-safe via random + retry
  const rand = () => crypto.randomBytes(4).toString('hex').toUpperCase().slice(0, 6);
  return `ATX-Q-${rand()}`;
}

